import type React from "react";

/**
 * default-shell 设计系统 token。
 * 全部 5 个 screen 共享,集中改色/字号都在这里。
 *
 * 原则:
 *   - 暗色 glass 基底 + 单 accent(温暖琥珀)
 *   - 4px spacing scale,silky 缓动 cubic-bezier(0.22, 1, 0.36, 1)
 *   - 字体走 fallback 链不引外部 CDN(运行时离线场景)
 */

export const tokens = {
  // ---- color ----
  bgOverlay: "rgba(11, 13, 16, 0.82)",
  bgOverlayStrong: "rgba(11, 13, 16, 0.92)",
  bgSurface: "rgba(255, 255, 255, 0.04)",
  bgElevated: "rgba(255, 255, 255, 0.07)",
  bgSunken: "rgba(0, 0, 0, 0.28)",

  borderSubtle: "rgba(255, 255, 255, 0.08)",
  borderRegular: "rgba(255, 255, 255, 0.14)",
  borderStrong: "rgba(255, 255, 255, 0.24)",
  borderAccent: "rgba(212, 165, 116, 0.55)",

  textPrimary: "#f5f5f7",
  textMuted: "rgba(245, 245, 247, 0.62)",
  textFaint: "rgba(245, 245, 247, 0.38)",
  textOnAccent: "#1a1410",

  accent: "#d4a574",
  accentSoft: "rgba(212, 165, 116, 0.16)",
  accentGlow: "rgba(212, 165, 116, 0.32)",

  danger: "#e0635a",
  dangerSoft: "rgba(224, 99, 90, 0.14)",

  // ---- typography ----
  // 风格:现代圆润黑体(geometric rounded sans),不要衬线/宋体
  // - fontDisplay  : 大字标题用,粗+圆润,系统圆润字体优先
  // - fontUI       : 正文/按钮用,中粗黑体
  // - fontMono     : 数字/timestamp,等宽
  fontDisplay:
    '"Plus Jakarta Sans", "M PLUS Rounded 1c", "PingFang SC", "Hiragino Sans GB", "HarmonyOS Sans", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, sans-serif',
  fontUI:
    '"Plus Jakarta Sans", "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "HarmonyOS Sans", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, "Helvetica Neue", sans-serif',
  fontMono:
    '"JetBrains Mono", "SF Mono", "Menlo", "Monaco", "Consolas", monospace',

  // ---- motion ----
  // quint-out 是公认最 silky 的 UI 缓动之一
  easeOut: "cubic-bezier(0.22, 1, 0.36, 1)",
  easeInOut: "cubic-bezier(0.65, 0, 0.35, 1)",
  easeIn: "cubic-bezier(0.64, 0, 0.78, 0)",
  // 2026-05 提速:从 180/280/420 收紧到 140/220/320。
  // 原值整体偏慢一档,玩家反馈"重、迟钝"。新值与 Vercel/Linear 这类
  // 现代 UI 的节奏对齐,同时保留 quint-out 的丝滑感。
  durFast: 140,
  durBase: 220,
  durSlow: 320,

  // ---- spacing & radius ----
  radiusSm: 6,
  radiusMd: 10,
  radiusLg: 16,
  radiusPill: 999,
} as const;

/**
 * 全局 keyframes 注入。
 *
 * 关键:必须在组件 render **之前** keyframes 已经在 DOM 里。
 * 否则第一帧浏览器 paint 时,animation 引用的 keyframe 还没解析,
 * 元素以"无 animation 默认样式"显示一帧,下一帧才进入 from 态 —— 就是闪一下。
 *
 * 解决:模块顶层立即调用一次,确保 import 这个文件即注入 style。
 * React mount 时 keyframes 已经存在 stylesheet,animation 立即生效。
 */
const SHARED_STYLE_ID = "avg-default-shell-shared-style";

export function ensureSharedStyle(): void {
  if (typeof document === "undefined") return;
  if (document.getElementById(SHARED_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = SHARED_STYLE_ID;
  style.textContent = `
    /* overlay:只动 opacity,backdrop-filter 用 inline 写死避免合成层重建闪烁 */
    @keyframes avg-overlay-in {
      from { opacity: 0; }
      to   { opacity: 1; }
    }
    @keyframes avg-overlay-out {
      from { opacity: 1; }
      to   { opacity: 0; }
    }
    @keyframes avg-content-rise {
      from { opacity: 0; transform: translateY(14px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes avg-content-fall {
      from { opacity: 1; transform: translateY(0); }
      to   { opacity: 0; transform: translateY(8px); }
    }
    @keyframes avg-stagger-rise {
      from { opacity: 0; transform: translateY(10px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes avg-title-reveal {
      from {
        opacity: 0;
        transform: translateY(18px);
        letter-spacing: 0.04em;
        filter: blur(6px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
        letter-spacing: 0.02em;
        filter: blur(0);
      }
    }
    @keyframes avg-page-slide-in-right {
      from { opacity: 0; transform: translateX(24px); }
      to   { opacity: 1; transform: translateX(0); }
    }
    @keyframes avg-page-slide-in-left {
      from { opacity: 0; transform: translateX(-24px); }
      to   { opacity: 1; transform: translateX(0); }
    }
    @keyframes avg-pulse-glow {
      0%, 100% { box-shadow: 0 0 0 0 rgba(212, 165, 116, 0); }
      50%      { box-shadow: 0 0 0 6px rgba(212, 165, 116, 0.06); }
    }
    @keyframes avg-row-rise {
      from { opacity: 0; transform: translateY(12px) scale(0.98); }
      to   { opacity: 1; transform: translateY(0) scale(1); }
    }
    @keyframes avg-card-rise {
      from { opacity: 0; transform: translateY(20px) scale(0.96); filter: blur(4px); }
      to   { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }
    @keyframes avg-header-slide {
      from { opacity: 0; transform: translateX(-16px); filter: blur(4px); }
      to   { opacity: 1; transform: translateX(0); filter: blur(0); }
    }
    @keyframes avg-line-expand {
      from { transform: scaleX(0); opacity: 0; }
      to   { transform: scaleX(1); opacity: 1; }
    }
    /* 工具栏按钮 active 态呼吸:用于标注当前处于 auto/skip 模式。
       双 keyframe 周期 2.4s,opacity + box-shadow 同步呼吸,
       动效柔和不抢戏。 */
    @keyframes avg-toolbar-active-breath {
      0%, 100% {
        opacity: 0.85;
        box-shadow: 0 0 0 0 rgba(212, 165, 116, 0.0);
      }
      50% {
        opacity: 1;
        box-shadow: 0 0 18px 2px rgba(212, 165, 116, 0.35);
      }
    }

    .avg-shell-scrollbar::-webkit-scrollbar { width: 8px; height: 8px; }
    .avg-shell-scrollbar::-webkit-scrollbar-track { background: transparent; }
    .avg-shell-scrollbar::-webkit-scrollbar-thumb {
      background: rgba(255, 255, 255, 0.08);
      border-radius: 999px;
      transition: background 220ms cubic-bezier(0.22, 1, 0.36, 1);
    }
    .avg-shell-scrollbar::-webkit-scrollbar-thumb:hover {
      background: rgba(255, 255, 255, 0.18);
    }

    @media (prefers-reduced-motion: reduce) {
      [class*="avg-anim"] { animation: none !important; }
    }
  `;
  document.head.appendChild(style);
}

// 模块加载时立即注入 —— 比组件 render 还早,彻底避免首帧无样式
// (浏览器 stylesheet 解析是同步的,这一行执行完 keyframes 就可用)
ensureSharedStyle();

/**
 * "动画起始态" inline style 工具集。
 *
 * 必须解决的问题:React render 后浏览器在 animation 真正生效前可能先
 * paint 一帧,那一帧用元素的 inline style(没有 opacity:0)→ 闪一下。
 * 修复:每个用 animation 的元素 spread 一个对应起始态进 inline style。
 *
 * 各起始态对应的 keyframe:
 *   hiddenStart        → avg-overlay-in / 任何只动 opacity 的
 *   contentStart       → avg-content-rise (translateY 14px)
 *   staggerStart       → avg-stagger-rise (translateY 10px)
 *   rowStart           → avg-row-rise (translateY 12px scale 0.98)
 *   cardStart          → avg-card-rise (translateY 20px scale 0.96 blur 4px)
 *   headerSlideStart   → avg-header-slide (translateX -16px blur 4px)
 *   lineExpandStart    → avg-line-expand (scaleX 0)
 *   titleRevealStart   → avg-title-reveal (translateY 18px blur 6px)
 *
 * 使用规则:**只要 inline 上写了 animation,就必须 spread 对应 start**。
 */
export const hiddenStart: React.CSSProperties = {
  opacity: 0,
};

export const contentStart: React.CSSProperties = {
  opacity: 0,
  transform: "translateY(14px)",
};

export const staggerStart: React.CSSProperties = {
  opacity: 0,
  transform: "translateY(10px)",
};

export const rowStart: React.CSSProperties = {
  opacity: 0,
  transform: "translateY(12px) scale(0.98)",
};

export const cardStart: React.CSSProperties = {
  opacity: 0,
  transform: "translateY(20px) scale(0.96)",
  filter: "blur(4px)",
};

export const headerSlideStart: React.CSSProperties = {
  opacity: 0,
  transform: "translateX(-16px)",
  filter: "blur(4px)",
};

export const lineExpandStart: React.CSSProperties = {
  opacity: 0,
  transform: "scaleX(0)",
};

export const titleRevealStart: React.CSSProperties = {
  opacity: 0,
  transform: "translateY(18px)",
  filter: "blur(6px)",
};
