import { useCallback, useEffect, useState } from "react";
import type React from "react";
import type { ExtensionContext } from "@avg-studio/sdk";
import { tokens } from "./shared-tokens";

/**
 * Screen 进出动画状态机 —— inline style 双 commit 版,根治闪烁。
 *
 * 真正的根因(终于找到了):
 *   useEffect 在 paint 之后跑 → 用 useLayoutEffect 也救不了。
 *   原因:engine 容器先 mount,我们的组件是后塞进去的,
 *   getComputedStyle 在 useLayoutEffect 时已经返回 opacity:1
 *   说明浏览器至少做过一次样式计算。在某些 React 调度路径下,
 *   useLayoutEffect 也未必早于浏览器第一次 paint。
 *
 * 唯一可靠的方案:
 *   把 hidden 起始态写在 inline style 里(JSX `style={{}}`),
 *   组件第一次 render 时 React commit DOM,inline opacity:0 就在那里了,
 *   浏览器再怎么调度 first paint 看到的都是 hidden。
 *
 * 实现:
 *   - useShown:状态 false → true,带双 rAF 触发
 *   - getStyles(shown, cfg):返回 inline style,shown=false 时是 hidden 态
 *   - 组件每次 render 把 getStyles(shown, cfg) spread 到 style
 *
 * 用法:
 *   const styles = useEnterStyles({
 *     hidden: { opacity: 0, transform: "translateY(14px)" },
 *     delay: 200,
 *   });
 *   <div style={{ ...静态样式, ...styles }}>
 */

export interface ScreenAnimatorConfig {
  hidden: React.CSSProperties;
  delay?: number;
  duration?: number;
  exitDuration?: number;
}

/**
 * 入场样式 hook。
 * 第一次 render 返回 hidden 态(transition:none),delay 毫秒后用 setTimeout
 * 触发 shown 态切换 —— shown 态写入正常 transition。
 *
 * 关键:返回的是 inline style 对象,组件直接 spread 到 JSX,
 * React 第一次 commit 时浏览器看到的就是 hidden style + transition:none,
 * 绝无闪烁,也不会误把"瞬间样式变化"当成 transition 触发点。
 *
 * 2026-05-24:回到 setTimeout(delay) 触发版,放弃 transition-delay 实现 stagger。
 *   - 现象:用 transition-delay 时,某些场景下 React 双 rAF 切到 shown
 *     发生太快,浏览器没确立 hidden 为稳定起点,transition 不触发,元素
 *     永久停在 hidden 态(computedOpacity:0 但 inlineOpacity:1) —— 整个
 *     设置界面的 Slider/Switch 都看不见、点不到。
 *   - 修复:每个元素自己 setTimeout(delay) 切 shown 态,因此 hidden→shown
 *     之间至少跨越一次浏览器 paint。同时第一次 commit 写 transition:none
 *     避免任何可能的"瞬时切换被吃掉"。
 *   - 副作用:delay=0 的元素需要至少一帧的 setTimeout(0),仍然走 task
 *     scheduling 而非 microtask,体感无差异。
 */

export function useEnterStyles(
  cfg: ScreenAnimatorConfig,
): React.CSSProperties {
  const [shown, setShown] = useState(false);
  const delay = cfg.delay ?? 0;
  const duration = cfg.duration ?? tokens.durSlow;

  useEffect(() => {
    // setTimeout 跨越整个 task,保证浏览器在中间画过一次 hidden 态,
    // shown 态 commit 时 transition 必然触发。
    const t = window.setTimeout(() => setShown(true), delay);
    return () => window.clearTimeout(t);
  }, [delay]);

  if (!shown) {
    // 第一次 commit:hidden 态 + transition:none。浏览器把这视为
    // "稳定起点",下一次 commit 切到 shown 时 transition 一定触发。
    return {
      ...cfg.hidden,
      transition: "none",
    };
  }

  const transition = `opacity ${duration}ms ${tokens.easeOut}, transform ${duration}ms ${tokens.easeOut}, filter ${duration}ms ${tokens.easeOut}`;
  return {
    opacity: 1,
    transform: "none",
    filter: "none",
    transition,
  };
}

/**
 * Overlay 入场样式:只动 opacity,backdrop-filter 别参与。
 */
export function useOverlayStyles(phase: ScreenPhase): React.CSSProperties {
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const t = window.setTimeout(() => setShown(true), 0);
    return () => window.clearTimeout(t);
  }, []);

  if (phase === "exit") {
    return {
      opacity: 0,
      transition: `opacity ${tokens.durFast}ms ${tokens.easeIn}`,
    };
  }

  if (!shown) {
    return { opacity: 0, transition: "none" };
  }

  return {
    opacity: 1,
    transition: `opacity ${tokens.durBase}ms ${tokens.easeOut}`,
  };
}

// ---- phase + exit ----

export type ScreenPhase = "shown" | "exit";

export interface UseScreenTransitionResult {
  phase: ScreenPhase;
  requestClose: () => void;
}

export function useScreenTransition(
  ctx: ExtensionContext,
  uiId: string,
  exitDuration: number = tokens.durFast,
): UseScreenTransitionResult {
  const [phase, setPhase] = useState<ScreenPhase>("shown");

  const requestClose = useCallback(() => {
    setPhase((prev) => (prev === "exit" ? prev : "exit"));
    window.setTimeout(() => {
      void ctx.ui.hide(uiId);
    }, exitDuration);
  }, [ctx, uiId, exitDuration]);

  return { phase, requestClose };
}

