import React, { useEffect, useState } from "react";
import {
  Extension,
  INTERNAL_SYSTEM_SLOT,
  extension,
  settings,
  useExtensionContext,
  type ExtensionContext,
  type SettingsBuilder,
} from "@avg-studio/sdk";
import { tokens } from "./shared-tokens";
import { usePressable } from "./use-pressable";
import { showToast } from "./toast";

/**
 * 对话工具栏。
 *
 * 设计要点:
 *   - pill 形状,底部居中,glass 效果
 *   - hover / active 通过圆角底色与强调色反馈
 *   - 入场:整体从下往上滑入(由 onRegister 触发的 ui.show 后立即播放)
 *   - 容器只占底部 80px(由 onRegister 配置),其余区域不接管点击
 */

const ITEMS = [
  { key: "skip", label: "跳过" },
  { key: "auto", label: "自动" },
  { key: "save", label: "存档" },
  { key: "load", label: "读档" },
  { key: "quickSave", label: "快存" },
  { key: "quickLoad", label: "快读" },
  { key: "history", label: "历史" },
  { key: "settings", label: "设置" },
  { key: "hide", label: "隐藏" },
] as const;

type ItemKey = (typeof ITEMS)[number]["key"];

const ToolbarComponent: React.FC = () => {
  const ctx = useExtensionContext();

  // ctx 已 scope 到 (extId, "toolbar"),useValue 自动加 "toolbar." 前缀。
  // 用 useValue(响应式)而非 get(一次性快照)—— 这样在设置面板里切换任一
  // 按钮开关,运行预览里的工具栏会立即重渲反映,不必等下一次对话推进。
  const showToolbar = ctx.settings.useValue<boolean>("showToolbar")[0] ?? true;
  const showSkip = ctx.settings.useValue<boolean>("showSkip")[0] ?? true;
  const showAuto = ctx.settings.useValue<boolean>("showAuto")[0] ?? true;
  const showSave = ctx.settings.useValue<boolean>("showSave")[0] ?? true;
  const showLoad = ctx.settings.useValue<boolean>("showLoad")[0] ?? true;
  const showQuickSave = ctx.settings.useValue<boolean>("showQuickSave")[0] ?? true;
  const showQuickLoad = ctx.settings.useValue<boolean>("showQuickLoad")[0] ?? true;
  const showHistory = ctx.settings.useValue<boolean>("showHistory")[0] ?? true;
  const showSettings = ctx.settings.useValue<boolean>("showSettings")[0] ?? true;
  const showHide = ctx.settings.useValue<boolean>("showHide")[0] ?? true;

  // engine 的 skip/auto 是 boolean 状态(进行中 / 关闭);拿来给按钮 active 着色
  // + AUTO/SKIP 角标。SDK 这两个 hook 内部订阅 ScriptingSystem 事件,模式变化
  // 时自动重渲。
  const skipActive = ctx.dialogue.useSkipMode();
  const autoActive = ctx.dialogue.useAutoMode();
  const activeSet: Partial<Record<ItemKey, "AUTO" | "SKIP">> = {
    skip: skipActive ? "SKIP" : undefined,
    auto: autoActive ? "AUTO" : undefined,
  };

  const visibleSet: Record<ItemKey, boolean> = {
    skip: showSkip,
    auto: showAuto,
    save: showSave,
    load: showLoad,
    quickSave: showQuickSave,
    quickLoad: showQuickLoad,
    history: showHistory,
    settings: showSettings,
    hide: showHide,
  };

  // 入场动画
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    const raf = requestAnimationFrame(() => setMounted(true));
    return () => cancelAnimationFrame(raf);
  }, []);

  const [hoverKey, setHoverKey] = useState<ItemKey | null>(null);

  // 总开关关闭时,渲染层兜底:即使 onRegister 的 subscribe 还没生效(例如
  // settings 初始化时序问题),组件这里也立即不渲染任何内容。
  if (!showToolbar) return null;

  const handle = (key: ItemKey) => {
    if (key === "skip") {
      // engine 的 skip 是 boolean 状态(进行中/关闭),跟 config.skipMode
      // ("全部跳过 / 只跳已读"策略)是两个维度。按钮要切的是状态;
      // 触发后 engine 默认"任意输入关闭",玩家点对话推进时会自然结束。
      ctx.dialogue.toggleSkipMode();
    } else if (key === "auto") {
      ctx.dialogue.toggleAutoMode();
    } else if (key === "settings") {
      // 2026-05 Internal Extension Points:不再读 slotUI 跨子模块,直接 invoke 系统槽位。
      // ctx.system 内部会查 projectConfig.systemBindings,失效时走 ULTIMATE_FALLBACK。
      void ctx.system.invoke(INTERNAL_SYSTEM_SLOT.Settings, undefined, {
        modal: true,
      });
    } else if (key === "save") {
      // 2026-05-19: 透传 mode payload,SaveScreen 渲染 save 模式按钮组
      void ctx.system.invoke(
        INTERNAL_SYSTEM_SLOT.Save,
        { mode: "save" },
        { modal: true },
      );
    } else if (key === "load") {
      // 走 Load slot 进入 load-only 视图(单按钮"读取"),跟存档的职责分开
      void ctx.system.invoke(
        INTERNAL_SYSTEM_SLOT.Load,
        { mode: "load", source: "game" },
        { modal: true },
      );
    } else if (key === "history") {
      void ctx.system.invoke(INTERNAL_SYSTEM_SLOT.History, undefined, {
        modal: true,
      });
    } else if (key === "quickSave") {
      ctx.archive
        .quickSave()
        .then(() => showToast("已快速存档", { type: "success" }))
        .catch((err) => {
          console.error("[toolbar] quickSave failed", err);
          showToast("快速存档失败", { type: "error" });
        });
    } else if (key === "quickLoad") {
      void (async () => {
        try {
          const loaded = await ctx.archive.quickLoad();
          if (!loaded) {
            showToast("没有可读取的快速存档", { type: "warn" });
          }
        } catch (err) {
          console.error("[toolbar] quickLoad failed", err);
          showToast("快速读档失败", { type: "error" });
        }
      })();
    } else if (key === "hide") {
      ctx.dialogue.hideBox();
    }
  };

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        pointerEvents: "none",
      }}
    >
      <div
        style={{
          pointerEvents: "auto",
          display: "flex",
          alignItems: "center",
          gap: 4,
          background: "rgba(11, 13, 16, 0.82)",
          backdropFilter: "blur(20px) saturate(160%)",
          WebkitBackdropFilter: "blur(20px) saturate(160%)",
          border: `1px solid ${tokens.borderSubtle}`,
          borderRadius: tokens.radiusPill,
          padding: "8px 12px",
          boxShadow:
            "0 18px 48px rgba(0,0,0,0.55), 0 1px 0 rgba(255,255,255,0.06) inset, 0 0 0 1px rgba(255,255,255,0.02)",
          transform: mounted ? "translateY(0)" : "translateY(20px)",
          opacity: mounted ? 1 : 0,
          transition: `transform ${tokens.durSlow}ms ${tokens.easeOut}, opacity ${tokens.durBase}ms ${tokens.easeOut}`,
        }}
      >
        {ITEMS.map((item) => {
          if (!visibleSet[item.key]) return null;
          return (
            <ToolbarButton
              key={item.key}
              isHover={hoverKey === item.key}
              activeBadge={activeSet[item.key]}
              onMouseEnter={() => setHoverKey(item.key)}
              onMouseLeave={() => setHoverKey(null)}
              onClick={() => handle(item.key)}
            >
              {item.label}
            </ToolbarButton>
          );
        })}
      </div>
    </div>
  );
};

// ---------- ToolbarButton ----------

const ToolbarButton: React.FC<{
  isHover: boolean;
  activeBadge?: "AUTO" | "SKIP";
  onMouseEnter: () => void;
  onMouseLeave: () => void;
  onClick: () => void;
  children: React.ReactNode;
}> = ({
  isHover,
  activeBadge,
  onMouseEnter,
  onMouseLeave,
  onClick,
  children,
}) => {
  const press = usePressable();
  const isActive = !!activeBadge;
  return (
    <button
      onMouseEnter={onMouseEnter}
      onMouseLeave={(e) => {
        onMouseLeave();
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={press.handlers.onPointerDown}
      onClick={onClick}
      style={{
        position: "relative",
        appearance: "none",
        // active 态优先级高于 hover —— 让"自动播放中"始终以 accent 配色呈现,
        // 即便鼠标没悬停也能识别。
        background: isActive
          ? tokens.accentSoft
          : isHover
            ? tokens.accentSoft
            : "transparent",
        border: "none",
        color: isActive
          ? tokens.accent
          : isHover
            ? tokens.accent
            : tokens.textPrimary,
        fontFamily: tokens.fontUI,
        fontSize: 14,
        fontWeight: 600,
        letterSpacing: "0.08em",
        padding: "10px 20px",
        borderRadius: tokens.radiusPill,
        cursor: "default",
        transform: press.pressed
          ? "scale(0.94) translateY(0)"
          : isHover
            ? "translateY(-2px) scale(1.02)"
            : "translateY(0) scale(1)",
        transition: `color ${tokens.durFast}ms ${tokens.easeOut}, background ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
        // 呼吸动画只在 active 态运行;否则 animation:none 让 transition 接管样式。
        animation: isActive
          ? "avg-toolbar-active-breath 2.4s ease-in-out infinite"
          : "none",
      }}
    >
      {children}
      {/* active 态角标 —— "AUTO" / "SKIP" 小号 mono,贴右上角,
          只有当 engine 上报"模式开启"时才挂上,关掉立即消失。 */}
      {activeBadge && (
        <span
          aria-hidden
          style={{
            position: "absolute",
            top: -4,
            right: -4,
            padding: "2px 6px",
            background: tokens.accent,
            color: tokens.textOnAccent,
            borderRadius: 999,
            fontFamily: tokens.fontMono,
            fontSize: 9,
            fontWeight: 700,
            letterSpacing: "0.12em",
            lineHeight: 1.1,
            boxShadow: `0 0 10px ${tokens.accentGlow}`,
            pointerEvents: "none",
          }}
        >
          {activeBadge}
        </span>
      )}
    </button>
  );
};

// 模块级去重 guard:registerAutonomousExtensions 在 dev 期间可能因 store 时序
// 被调多次。重复跑 onRegister 会重复订阅 dialogue:changed 事件,行为变怪。
//
// ⚠️ 注意:ctx.getHost() 每次调用都返回**新对象**(engine-sdk-context line 549,
// `return { application, mode }`),所以**不能**用 host 对象本身做 WeakSet key,
// 那样去重永远失败。改用 host.application(engine 实例引用,稳定)做 key ——
// 同一个 engine 实例只让 onRegister 跑一次。
// 注意:这个 guard 的 lifecycle 是 module 级,Vite HMR reload 这个文件时
// WeakSet 会被新建一个空的,所以 HMR 后重新注册一次是允许的。
const registeredEngines = new WeakSet<object>();

@extension({
  id: "toolbar",
  label: "工具栏",
  exposeUI: false, // 保留跟随对话显隐的控制器,React 版不再进入 UI 列表
  autonomous: true, // toolbar 跟随 dialogue 显隐
  // 本类只负责跟随 dialogue 显隐；实际打开哪份工具栏由 Toolbar 系统槽位决定。
})
export class Toolbar extends Extension {
  static settings = settings((s: SettingsBuilder) => ({
    // 总开关:整个工具栏是否在对话期间显示。
    // 关闭后,所有按钮一并隐藏 —— 这是相对下面按钮级开关更高一层的"模块级"开关。
    showToolbar: s.boolean("显示对话工具栏").default(true),
    // 下面每个按钮级开关用 enabledWhen 挂到总开关上:总开关关掉时,
    // 它们在设置面板里置灰(不可点),但各自的值保持不变 —— 重开总开关后恢复。
    showSkip: s.boolean("显示跳过按钮").default(true).enabledWhen("showToolbar"),
    showAuto: s.boolean("显示自动播放按钮").default(true).enabledWhen("showToolbar"),
    showSave: s.boolean("显示存档按钮").default(true).enabledWhen("showToolbar"),
    showLoad: s.boolean("显示读档按钮").default(true).enabledWhen("showToolbar"),
    showQuickSave: s
      .boolean("显示快速存档按钮")
      .default(true)
      .enabledWhen("showToolbar"),
    showQuickLoad: s
      .boolean("显示快速读档按钮")
      .default(true)
      .enabledWhen("showToolbar"),
    showHistory: s.boolean("显示历史按钮").default(true).enabledWhen("showToolbar"),
    showSettings: s.boolean("显示设置按钮").default(true).enabledWhen("showToolbar"),
    showHide: s.boolean("显示隐藏对话框按钮").default(true).enabledWhen("showToolbar"),
  }));

  /**
   * Toolbar 跟随 dialogue 显隐 —— 当 dialogue.line() 非空时显示,空时隐藏。
   * 订阅 dialogue:changed,值变 → ensureToolbarVisibility 同步状态。
   */
  static onRegister(ctx: ExtensionContext): void {
    // 用 engine 实例做 stable key 去重 —— getHost() 返回的对象每次都是新的,
    // 不能直接当 WeakSet key(见上方注释)。
    const host = ctx.getHost() as { application?: object } | null;
    const engineKey = host?.application;
    if (engineKey && registeredEngines.has(engineKey)) return;
    if (engineKey) registeredEngines.add(engineKey);

    let desiredVisible = false;
    // null 表示刚注册、尚未向槽位宿主同步过。初次无对白时仍执行一次 close，
    // 以清理 HMR 前一代控制器可能留下的工具栏。
    let appliedVisible: boolean | null = null;
    let reconciling = false;
    let syncRevision = 0;

    /**
     * 串行收敛到最新显隐意图。Skip 会在几十毫秒内跨过多次对白销毁/重建，
     * invoke 与 close 不能并发：旧 invoke 完成后若调用槽位级 close，会把新一代
     * 工具栏一起关掉。单 worker 在每次 await 后重读 desiredVisible，中间状态
     * 自动合并，只让当前最新意图决定下一步。
     */
    const reconcile = async () => {
      if (reconciling) return;
      reconciling = true;

      try {
        while (
          appliedVisible === null ||
          appliedVisible !== desiredVisible
        ) {
          const targetVisible = desiredVisible;
          const attemptRevision = syncRevision;
          try {
            if (targetVisible) {
              await ctx.system.invoke(INTERNAL_SYSTEM_SLOT.Toolbar);
            } else {
              await ctx.system.close(INTERNAL_SYSTEM_SLOT.Toolbar);
            }
            appliedVisible = targetVisible;
          } catch (err) {
            // 操作期间收到过新同步事件时，失败的是过期尝试，继续按最新状态收敛。
            // 没有更新事件的当前动作失败则停止本轮，等待下一次事件重试，
            // 避免宿主持久失败时形成无间隔重试循环。
            if (
              targetVisible !== desiredVisible ||
              attemptRevision !== syncRevision
            ) {
              continue;
            }
            console.warn(
              targetVisible
                ? "[toolbar] 工具栏系统槽位打开失败"
                : "[toolbar] 工具栏系统槽位关闭失败",
              err,
            );
            return;
          }
        }
      } finally {
        reconciling = false;
      }
    };

    const sync = () => {
      // 总开关:用户在设置面板关掉"显示对话工具栏"后,即便在对话中也不显示。
      const enabled = ctx.settings.get<boolean>("showToolbar") ?? true;
      const inDialogue = ctx.dialogue.line() !== null;
      desiredVisible = enabled && inDialogue;
      syncRevision += 1;
      // 重复的 line/hidden 事件只会唤醒同一个 worker；若上次宿主操作失败，
      // 下一次相同状态事件也可在这里安全重试。
      void reconcile();
    };

    ctx.subscribe("dialogue:changed", sync);
    // 订阅总开关变化 —— 玩家在 Settings 面板里切换"显示对话工具栏"时,
    // 不用退出对话也能立即生效。
    ctx.settings.subscribe<boolean>("showToolbar", sync);
    // 启动时立即同步一次(可能 onRegister 时 dialogue 已有内容)
    sync();
  }

  render() {
    return { component: ToolbarComponent, props: {} };
  }
}
