import React, { useEffect, useRef, useState } from "react";
import {
  Extension,
  INTERNAL_SYSTEM_SLOT,
  extension,
  settings,
  useExtensionContext,
  type ExtensionContext,
  type SettingsBuilder,
} from "@avg-studio/sdk";
import {
  FALLBACK_SETTINGS_TEXT_SPEED,
  normalizeSettingsTextSpeed,
} from "./settings-defaults";
import { tokens } from "./shared-tokens";
import {
  useScreenTransition,
  useOverlayStyles,
  useEnterStyles,
  type ScreenPhase,
} from "./use-screen-transition";
import { usePressable } from "./use-pressable";
import { ScreenHeader, SecondaryButton, CloseButton } from "./screen-chrome";

/**
 * 设置画面 —— 大气版 + 全元素 stagger 入场。
 *
 * 入场编排:
 *   1. overlay backdrop blur 0→24 (overlayAnimation)
 *   2. header 标题左滑 + blur(60ms)
 *   3. 每个 Section 标题 stagger
 *   4. Section 内每个 Row 都有自己的 stagger delay
 *
 * 所有交互元素带 press 反馈(scale + brightness)。
 */

const SettingsScreenComponent: React.FC = () => {
  const ctx = useExtensionContext();

  // ctx 已 scope 到 (extId, "settings-screen"),get 自动加 "settings-screen." 前缀
  const allowReset = ctx.settings.get<boolean>("allowReset") ?? true;
  const { phase, requestClose } = useScreenTransition(ctx, "settings-screen");

  const [masterVolume, setMasterVolume] = ctx.config.useValue("masterVolume");
  const [bgmVolume, setBgmVolume] = ctx.config.useValue("bgmVolume");
  const [seVolume, setSeVolume] = ctx.config.useValue("seVolume");
  const [voiceVolume, setVoiceVolume] = ctx.config.useValue("voiceVolume");
  const [textSpeed, setTextSpeed] = ctx.config.useValue("textSpeed");
  const [autoSpeed, setAutoSpeed] = ctx.config.useValue("autoModeTextSpeed");
  const [skipMode, setSkipMode] = ctx.config.useValue("skipMode");
  const [stopVoice, setStopVoice] = ctx.config.useValue(
    "stopVoiceOnNextDialogue",
  );
  const canToggleFullscreen = ctx.game.window.canFullscreen();
  const [fullscreen, setFullscreen] = ctx.game.window.useFullscreen();

  const onReset = () => {
    void ctx.config.reset();
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") requestClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [requestClose]);

  // 控制按行 stagger 的 delay 起点
  // 2026-05 提速:200/60 → 120/35,整段尾巴从 ~640ms 缩到 ~360ms。
  const ROW_BASE = 120;
  const ROW_GAP = 35;
  const SECTION_GAP = 80; // 第二个 section 相对第一个的 row 起点偏移
  const DISPLAY_SECTION_DELAY = ROW_BASE + SECTION_GAP * 2;

  const overlayStyles = useOverlayStyles(phase);

  // backdrop-filter 延迟 attach:第一次 mount 不带 backdrop-filter,
  // 避免 GPU 创建滤镜合成层那一帧的闪光。等 100ms 后再加上去,
  // 此时入场动画也已经过半,backdrop blur 自然渐入。
  const [backdropOn, setBackdropOn] = useState(false);
  useEffect(() => {
    const t = window.setTimeout(() => setBackdropOn(true), 100);
    return () => window.clearTimeout(t);
  }, []);

  // 右键关闭:桌面应用直觉,任何 overlay 单击右键即"返回上一层"。
  const onContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
    requestClose();
  };

  return (
    <div
      onContextMenu={onContextMenu}
      style={{
        position: "absolute",
        inset: 0,
        background: tokens.bgOverlay,
        backdropFilter: backdropOn ? "blur(24px)" : "none",
        WebkitBackdropFilter: backdropOn ? "blur(24px)" : "none",
        color: tokens.textPrimary,
        fontFamily: tokens.fontUI,
        display: "flex",
        flexDirection: "column",
        ...overlayStyles,
      }}
    >
      {/* —— Header —— */}
      <ScreenHeader
        eyebrow="Preferences"
        title="设置"
        phase={phase}
        rightSlot={
          <>
            {allowReset && <SecondaryButton onClick={onReset}>恢复默认</SecondaryButton>}
            <CloseButton onClick={requestClose} />
          </>
        }
      />

      {/* —— 内容区 —— */}
      <div
        className="avg-shell-scrollbar"
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "32px 80px 80px",
        }}
      >
        <div
          style={{
            maxWidth: 880,
            margin: "0 auto",
            display: "flex",
            flexDirection: "column",
            gap: 40,
          }}
        >
          <Section title="音量" sectionDelay={ROW_BASE - 40} phase={phase}>
            <SliderRow
              label="主音量"
              value={(masterVolume as number) ?? 100}
              onChange={(v) => setMasterVolume(v as never)}
              delay={ROW_BASE + ROW_GAP * 0}
              phase={phase}
            />
            <SliderRow
              label="背景音乐"
              value={(bgmVolume as number) ?? 100}
              onChange={(v) => setBgmVolume(v as never)}
              delay={ROW_BASE + ROW_GAP * 1}
              phase={phase}
            />
            <SliderRow
              label="音效"
              value={(seVolume as number) ?? 100}
              onChange={(v) => setSeVolume(v as never)}
              delay={ROW_BASE + ROW_GAP * 2}
              phase={phase}
            />
            <SliderRow
              label="语音"
              value={(voiceVolume as number) ?? 100}
              onChange={(v) => setVoiceVolume(v as never)}
              delay={ROW_BASE + ROW_GAP * 3}
              phase={phase}
              isLast
            />
          </Section>

          <Section title="文本与播放" sectionDelay={ROW_BASE + SECTION_GAP} phase={phase}>
            {/*
              文本速度 / 自动播放速度:
              - 设置菜单与引擎存储共用 0-100，数字越大越快
              - 50 表示作者当前速度的 1x，100 为瞬间显示
              滑块只改玩家倍率，剧情 Block 或样式在运行中改基础速度时，
              滑块位置不会跟着跳动。
            */}
            <SliderRow
              label="文本速度"
              value={normalizeSettingsTextSpeed(
                textSpeed ?? FALLBACK_SETTINGS_TEXT_SPEED,
              )}
              onChange={(v) =>
                setTextSpeed(normalizeSettingsTextSpeed(v) as never)
              }
              delay={ROW_BASE + SECTION_GAP + ROW_GAP * 1}
              phase={phase}
            />
            <SliderRow
              label="自动播放速度"
              value={normalizeSettingsTextSpeed(
                autoSpeed ?? FALLBACK_SETTINGS_TEXT_SPEED,
              )}
              onChange={(v) =>
                setAutoSpeed(normalizeSettingsTextSpeed(v) as never)
              }
              delay={ROW_BASE + SECTION_GAP + ROW_GAP * 2}
              phase={phase}
            />
            <Row label="跳过模式" delay={ROW_BASE + SECTION_GAP + ROW_GAP * 3} phase={phase}>
              <Segmented
                options={[
                  { value: "read", label: "只跳已读" },
                  { value: "all", label: "全部跳过" },
                ]}
                value={(skipMode as string) ?? "read"}
                onChange={(v) => setSkipMode(v as never)}
              />
            </Row>
            <Row label="切换对话停止上句语音" delay={ROW_BASE + SECTION_GAP + ROW_GAP * 4} phase={phase} isLast>
              <Switch
                checked={!!stopVoice}
                onChange={(v) => setStopVoice(v as never)}
              />
            </Row>
          </Section>

          {canToggleFullscreen && (
            <Section
              title="显示"
              sectionDelay={DISPLAY_SECTION_DELAY}
              phase={phase}
            >
              <Row
                label="屏幕模式"
                delay={DISPLAY_SECTION_DELAY + ROW_GAP}
                phase={phase}
                isLast
              >
                <Segmented
                  options={[
                    { value: "windowed", label: "窗口" },
                    { value: "fullscreen", label: "全屏" },
                  ]}
                  value={fullscreen ? "fullscreen" : "windowed"}
                  onChange={(v) => setFullscreen(v === "fullscreen")}
                />
              </Row>
            </Section>
          )}
        </div>
      </div>
    </div>
  );
};

// ---------- Section ----------

const Section: React.FC<{
  title: string;
  sectionDelay: number;
  phase: ScreenPhase;
  children: React.ReactNode;
}> = ({ title, sectionDelay, children }) => {
  const headerStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateX(-16px)" },
    delay: sectionDelay,
  });
  const lineStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "scaleX(0)" },
    delay: sectionDelay + 60,
  });

  return (
    <section>
      <div
        style={{
          display: "flex",
          alignItems: "baseline",
          gap: 16,
          marginBottom: 20,
          ...headerStyles,
        }}
      >
        <h3
          style={{
            fontFamily: tokens.fontDisplay,
            fontSize: 24,
            fontWeight: 700,
            margin: 0,
            letterSpacing: "0.005em",
          }}
        >
          {title}
        </h3>
        <div
          style={{
            flex: 1,
            height: 1,
            background: `linear-gradient(90deg, ${tokens.borderRegular} 0%, transparent 100%)`,
            transformOrigin: "left",
            ...lineStyles,
          }}
        />
      </div>
      <div
        style={{
          background: tokens.bgSurface,
          border: `1px solid ${tokens.borderSubtle}`,
          borderRadius: tokens.radiusLg,
          padding: "8px 32px",
          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.03)",
        }}
      >
        {children}
      </div>
    </section>
  );
};

// ---------- Row ----------

const Row: React.FC<{
  label: string;
  delay: number;
  phase: ScreenPhase;
  isLast?: boolean;
  children: React.ReactNode;
}> = ({ label, delay, isLast, children }) => {
  const styles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(12px) scale(0.98)" },
    delay,
  });
  return (
  <div
    style={{
      display: "flex",
      alignItems: "center",
      gap: 24,
      padding: "20px 0",
      borderBottom: isLast ? "none" : `1px solid ${tokens.borderSubtle}`,
      ...styles,
    }}
  >
    <div
      style={{
        minWidth: 200,
        fontSize: 16,
        color: tokens.textPrimary,
        fontWeight: 500,
      }}
    >
      {label}
    </div>
    <div
      style={{
        flex: 1,
        display: "flex",
        justifyContent: "flex-end",
        alignItems: "center",
      }}
    >
      {children}
    </div>
  </div>
  );
};

const SliderRow: React.FC<{
  label: string;
  value: number;
  onChange: (v: number) => void;
  delay: number;
  phase: ScreenPhase;
  isLast?: boolean;
}> = ({ label, value, onChange, delay, phase, isLast }) => {
  const safeDisplayValue = Number.isFinite(value)
    ? Math.max(0, Math.min(100, value))
    : 0;
  return (
    <Row label={label} delay={delay} phase={phase} isLast={isLast}>
      <Slider value={safeDisplayValue} onChange={onChange} min={0} max={100} />
      <div
        style={{
          fontFamily: tokens.fontMono,
          fontSize: 14,
          color: tokens.textPrimary,
          minWidth: 48,
          textAlign: "right",
          paddingLeft: 20,
          fontVariantNumeric: "tabular-nums",
          fontWeight: 600,
        }}
      >
        {Math.round(safeDisplayValue)}
      </div>
    </Row>
  );
};

// ---------- Slider ----------

const Slider: React.FC<{
  value: number;
  min: number;
  max: number;
  onChange: (v: number) => void;
}> = ({ value, min, max, onChange }) => {
  const trackRef = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState(false);
  const [hover, setHover] = useState(false);
  const safeValue = Number.isFinite(value)
    ? Math.max(min, Math.min(max, value))
    : min;
  const pct = ((safeValue - min) / (max - min)) * 100;

  const updateFromClientX = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    onChange(min + ratio * (max - min));
  };

  useEffect(() => {
    if (!dragging) return;
    const onMove = (e: PointerEvent) => updateFromClientX(e.clientX);
    const onUp = () => setDragging(false);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dragging]);

  return (
    <div
      ref={trackRef}
      onPointerDown={(e) => {
        setDragging(true);
        updateFromClientX(e.clientX);
      }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        position: "relative",
        flex: 1,
        height: 28,
        display: "flex",
        alignItems: "center",
        cursor: "default",
        userSelect: "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          height: 5,
          background: tokens.borderSubtle,
          borderRadius: 999,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: 0,
          width: `${pct}%`,
          height: 5,
          background: `linear-gradient(90deg, ${tokens.accent} 0%, ${tokens.accent} 100%)`,
          borderRadius: 999,
          boxShadow: hover || dragging ? `0 0 12px ${tokens.accentGlow}` : "none",
          transition: dragging
            ? "none"
            : `width ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durBase}ms ${tokens.easeOut}`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: `${pct}%`,
          width: 20,
          height: 20,
          marginLeft: -10,
          borderRadius: "50%",
          background: tokens.textPrimary,
          boxShadow:
            dragging || hover
              ? `0 0 0 8px ${tokens.accentSoft}, 0 4px 12px rgba(0,0,0,0.5)`
              : "0 2px 8px rgba(0,0,0,0.4)",
          transform:
            dragging ? "scale(1.18)" : hover ? "scale(1.08)" : "scale(1)",
          transition: dragging
            ? `box-shadow ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`
            : `left ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
        }}
      />
    </div>
  );
};

// ---------- Segmented ----------

const Segmented: React.FC<{
  options: Array<{ value: string; label: string }>;
  value: string;
  onChange: (v: string) => void;
}> = ({ options, value, onChange }) => {
  const idx = options.findIndex((o) => o.value === value);
  const safeIdx = idx >= 0 ? idx : 0;
  return (
    <div
      style={{
        position: "relative",
        display: "inline-flex",
        background: tokens.bgSunken,
        border: `1px solid ${tokens.borderSubtle}`,
        borderRadius: tokens.radiusMd,
        padding: 4,
      }}
    >
      <div
        style={{
          position: "absolute",
          top: 4,
          bottom: 4,
          left: `calc(${safeIdx} * (100% - 8px) / ${options.length} + 4px)`,
          width: `calc((100% - 8px) / ${options.length})`,
          background: tokens.accent,
          borderRadius: tokens.radiusSm,
          transition: `left ${tokens.durBase}ms ${tokens.easeOut}`,
          boxShadow: `0 2px 12px ${tokens.accentGlow}`,
        }}
      />
      {options.map((opt) => (
        <SegmentedItem
          key={opt.value}
          active={opt.value === value}
          onClick={() => onChange(opt.value)}
        >
          {opt.label}
        </SegmentedItem>
      ))}
    </div>
  );
};

const SegmentedItem: React.FC<{
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}> = ({ active, onClick, children }) => {
  const press = usePressable();
  return (
    <button
      {...press.handlers}
      onClick={onClick}
      style={{
        position: "relative",
        zIndex: 1,
        appearance: "none",
        background: "transparent",
        border: "none",
        padding: "10px 24px",
        fontSize: 14,
        fontFamily: tokens.fontUI,
        fontWeight: 600,
        letterSpacing: "0.02em",
        color: active ? tokens.textOnAccent : tokens.textMuted,
        cursor: "default",
        minWidth: 116,
        transform: press.pressed ? "scale(0.96)" : "scale(1)",
        transition: `color ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
      }}
    >
      {children}
    </button>
  );
};

// ---------- Switch ----------

const Switch: React.FC<{
  checked: boolean;
  onChange: (v: boolean) => void;
}> = ({ checked, onChange }) => {
  const press = usePressable();
  return (
    <button
      {...press.handlers}
      onClick={() => onChange(!checked)}
      role="switch"
      aria-checked={checked}
      style={{
        appearance: "none",
        position: "relative",
        width: 52,
        height: 30,
        borderRadius: 999,
        border: `1px solid ${checked ? tokens.borderAccent : tokens.borderRegular}`,
        background: checked ? tokens.accent : tokens.bgSunken,
        cursor: "default",
        padding: 0,
        transform: press.pressed ? "scale(0.94)" : "scale(1)",
        transition: `background ${tokens.durBase}ms ${tokens.easeOut}, border-color ${tokens.durBase}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
        boxShadow: checked ? `0 0 16px ${tokens.accentGlow}` : "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: 3,
          left: checked ? 24 : 3,
          width: 22,
          height: 22,
          borderRadius: "50%",
          background: checked ? tokens.textOnAccent : tokens.textPrimary,
          boxShadow: "0 2px 6px rgba(0,0,0,0.5)",
          transition: `left ${tokens.durBase}ms ${tokens.easeOut}, background ${tokens.durBase}ms ${tokens.easeOut}`,
        }}
      />
    </button>
  );
};

@extension({
  id: "settings-screen",
  label: "设置画面",
  exposeUI: false, // 保留可视化界面控制器,React 版不再进入 UI 列表
  // 2026-05 Internal Extension Points §6.1:声明本 UI 实现"设置"槽位。
  supportsSlot: INTERNAL_SYSTEM_SLOT.Settings,
})
export class SettingsScreen extends Extension {
  // 2026-05 Internal Extension Points:删除 slotUI 字段,改由项目级
  // systemBindings 控制(在 Studio 项目设置 → 系统 面板配置)。
  static settings = settings((s: SettingsBuilder) => ({
    allowReset: s.boolean("允许重置默认").default(true),
  }));

  /**
   * 可视化设置界面(本扩展 ui/settings-screen.json)的控制器 ——
   * 扩展复合容器(视图/控制器)的第一个 dogfooding:布局住在 JSON
   * (编辑器可看可拷可改),动态行为在这里操作控件。
   * 「设置」槽位默认绑定 "ui:@avg.internal.default-shell/settings-screen"。
   * 本类只保留控制器职责,不再向 UI host 导出 React 版画面。
   */
  static onRegister(ctx: ExtensionContext): void {
    ctx.visualUI.onOpen(
      "@avg.internal.default-shell/settings-screen",
      (view) => {
        // 平台不支持全屏(如 Web 导出受限环境)→ 整个「显示」区隐藏,
        // 与 React 版的条件渲染同语义
        if (!ctx.game.window.canFullscreen()) {
          for (const refId of [
            "display-card",
            "display-title",
            "display-label",
            "display-switch",
          ]) {
            view.get(refId)?.setHidden(true);
          }
        }

        // 保留控制器监听以兼容已经被用户覆盖、尚未带 config.reset 动作的旧 JSON。
        // 新版默认 JSON 同时有声明式动作；SDK 会合并同一轮 reset，避免重复写盘。
        const resetButton = view.get("reset-btn");
        let feedbackTimer: ReturnType<typeof setTimeout> | undefined;
        resetButton?.on("click", () => {
          if (feedbackTimer !== undefined) clearTimeout(feedbackTimer);
          resetButton.setProps({ text: "正在恢复…" });
          void ctx.config
            .reset()
            .then(() => {
              resetButton.setProps({ text: "已恢复" });
              feedbackTimer = setTimeout(() => {
                resetButton.setProps({ text: "恢复默认" });
              }, 1000);
            })
            .catch((err) => {
              console.error("[settings-screen] 恢复默认设置失败", err);
              resetButton.setProps({ text: "恢复失败" });
              feedbackTimer = setTimeout(() => {
                resetButton.setProps({ text: "恢复默认" });
              }, 1400);
            });
        });
        view.onClose(() => {
          if (feedbackTimer !== undefined) clearTimeout(feedbackTimer);
        });
      },
    );
  }

  render() {
    return { component: SettingsScreenComponent, props: {} };
  }
}
