/**
 * default-shell 全局 toast。
 *
 * 不走 React tree(SaveScreen 关掉时 root 会卸载,F5 触发时它根本没挂载)。
 * 直接操作 DOM,创建一个固定定位的容器,push 消息进去,3 秒自动淡出。
 *
 * 用法:
 *   showToast("已存档")
 *   showToast("读档成功", { type: "success" })
 *   showToast("没有可读取的快速存档", { type: "warn" })
 */

import { tokens } from "./shared-tokens";

const CONTAINER_ID = "avg-default-shell-toast-container";
const TOAST_DURATION_MS = 2400;
const FADE_DURATION_MS = 220;

export type ToastType = "info" | "success" | "warn" | "error";

interface ToastOptions {
  type?: ToastType;
  /** 持续显示时间,默认 2400ms */
  durationMs?: number;
}

// 历史:容器曾尝试过两种挂载位置:
//   1. document.body —— 在 Studio 里 toast 弹到了编辑器 UI 上(因为 Studio
//      主窗口的 body 跟游戏画面不是同一棵子树)
//   2. #game-view —— 解决了"弹到编辑器上"的问题,但 #game-view 是 React
//      管理的节点,我们的 appendChild/remove 跟 React 的 diff 撞了,
//      触发 "Failed to execute 'removeChild': not a child of this node"
//      → ExtensionLivePreview 整棵树挂掉 → 白屏
//
// 现版:挂到 document.body(完全脱离 React 管理),但定位时**动态读取
// #game-view 的 getBoundingClientRect 并 sync** 到容器位置,这样视觉上仍然
// 看起来在游戏画面内,Studio Preview / 独立 Player 都正确。
function syncContainerToGameView(el: HTMLDivElement): void {
  const gameView = document.getElementById("game-view");
  if (!gameView) {
    // 找不到 game-view 时退化到 viewport bottom-center
    el.style.left = "50%";
    el.style.bottom = "32px";
    el.style.top = "auto";
    el.style.right = "auto";
    el.style.width = "auto";
    return;
  }
  const rect = gameView.getBoundingClientRect();
  // 用 left/top/width 占据 game-view 整个横向范围,容器 flex 居中子 toast,
  // bottom-32 偏移仍然有效(translateX:-50% 在 flex 模式下不需要,改用 align)
  el.style.left = `${rect.left}px`;
  el.style.top = `${rect.bottom - 32 - 64}px`; // 上沿 = game-view 底部 - bottom(32) - 容器自身高度(估)
  el.style.width = `${rect.width}px`;
  el.style.bottom = "auto";
  el.style.right = "auto";
}

function ensureContainer(): HTMLDivElement | null {
  if (typeof document === "undefined") return null;
  let el = document.getElementById(CONTAINER_ID) as HTMLDivElement | null;
  if (el) {
    syncContainerToGameView(el);
    return el;
  }

  el = document.createElement("div");
  el.id = CONTAINER_ID;
  el.style.cssText = [
    "position: fixed",
    // 跟引擎 engine-mask 同款 max int 层级,确保压在 SaveScreen overlay 之上。
    // SaveScreen 自己用 position:absolute 没设 z-index,但被引擎 UISystem
    // 装进 topmost 容器后实际有高层级,普通 99999 可能被盖。
    "z-index: 2147483647",
    "display: flex",
    "flex-direction: column",
    "align-items: center",
    "justify-content: flex-end",
    "gap: 8px",
    "pointer-events: none",
  ].join(";");
  document.body.appendChild(el);
  syncContainerToGameView(el);

  // game-view 尺寸/位置可能变(窗口 resize / Studio 分割条拖动),
  // 用 ResizeObserver 跟随。容器一直在 body 不会被 React 清理,observer
  // 不需要在 toast 消失时 disconnect —— 长期 piggyback 在 game-view 上几乎
  // 零开销,且 toast 用得很少。
  const gameView = document.getElementById("game-view");
  if (gameView && typeof ResizeObserver !== "undefined") {
    const ro = new ResizeObserver(() => syncContainerToGameView(el!));
    ro.observe(gameView);
  }

  return el;
}

const ICON: Record<ToastType, string> = {
  info: "·",
  success: "✓",
  warn: "!",
  error: "×",
};

const ACCENT_BY_TYPE: Record<ToastType, string> = {
  info: tokens.textMuted,
  success: tokens.accent,
  warn: tokens.accent,
  error: tokens.danger,
};

export function showToast(message: string, opts: ToastOptions = {}): void {
  const container = ensureContainer();
  if (!container) return;
  const type = opts.type ?? "info";
  const duration = opts.durationMs ?? TOAST_DURATION_MS;

  const toast = document.createElement("div");
  toast.style.cssText = [
    `font-family: ${tokens.fontUI}`,
    "font-size: 13px",
    "font-weight: 500",
    "letter-spacing: 0.04em",
    `color: ${tokens.textPrimary}`,
    "background: rgba(11, 13, 16, 0.88)",
    `border: 1px solid ${tokens.borderRegular}`,
    "border-radius: 8px",
    "padding: 10px 16px",
    "backdrop-filter: blur(12px)",
    "-webkit-backdrop-filter: blur(12px)",
    "box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4)",
    "display: flex",
    "align-items: center",
    "gap: 10px",
    "opacity: 0",
    "transform: translateY(8px)",
    `transition: opacity ${FADE_DURATION_MS}ms ${tokens.easeOut}, transform ${FADE_DURATION_MS}ms ${tokens.easeOut}`,
    "max-width: 480px",
    "pointer-events: none",
  ].join(";");

  const dot = document.createElement("span");
  dot.textContent = ICON[type];
  dot.style.cssText = [
    `color: ${ACCENT_BY_TYPE[type]}`,
    "font-weight: 700",
    "font-size: 14px",
    "line-height: 1",
    "flex-shrink: 0",
  ].join(";");
  toast.appendChild(dot);

  const text = document.createElement("span");
  text.textContent = message;
  toast.appendChild(text);

  container.appendChild(toast);

  // 强制 reflow 触发 transition
  void toast.offsetHeight;
  toast.style.opacity = "1";
  toast.style.transform = "translateY(0)";

  // 淡出 + 移除
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(8px)";
    setTimeout(() => {
      toast.remove();
      // 容器空了就移除,避免长期占位
      if (container.childElementCount === 0) container.remove();
    }, FADE_DURATION_MS);
  }, duration);
}
