import {
  NEUTRAL_TEXT_SPEED_SETTING,
  normalizeTextSpeedSetting,
} from "../../../engine/system/text-speed-scale";

export const FALLBACK_SETTINGS_TEXT_SPEED = NEUTRAL_TEXT_SPEED_SETTING;

export function getResetTextSpeed(): number {
  return FALLBACK_SETTINGS_TEXT_SPEED;
}

/** 设置菜单与持久化共用 0-100；50=1x，100=瞬显。 */
export function normalizeSettingsTextSpeed(value: unknown): number {
  return normalizeTextSpeedSetting(value);
}
