import type { GalleryLayer } from "@avg-studio/sdk";

/** 一条鉴赏条目(存进存档的形态,JSON 可序列化)。 */
export interface GalleryEntry {
  entryId: string;
  title: string;
  /** 来源场景 id —— 兼作去重 key 填充 entryId。 */
  sceneId: string;
  /** 场景图层快照 —— 缩略图叠层 + 大图临时引擎渲染都用它。 */
  layers: GalleryLayer[];
  /**
   * 顶层封面图(=layers 首个有效层的 assetPath)。可视化「数据列表」组件只能取
   * 顶层字符串字段,取不到嵌套的 layers[].assetPath,所以写入时顺手拍平一张封面
   * 供 data-list 的 imageField 绑定。老存档没有此字段 → data-list 显示占位块(不崩)。
   */
  coverImage?: string;
}

/** 一条音乐鉴赏记录。audioUri 保留项目资源引用，播放时再由运行时解析。 */
export interface MusicGalleryEntry {
  entryId: string;
  title: string;
  audioUri: string;
  artist?: string;
  description?: string;
}

/** 一条剧情片段鉴赏记录。chapterId 可选，缺省时由运行时按当前章节解析。 */
export interface FragmentGalleryEntry {
  entryId: string;
  title: string;
  fragmentId: string;
  chapterId?: string;
  description?: string;
  coverImage?: string;
}

/**
 * 从动作块 paramsJson 里取出 `_sceneLayers` 字符串后,解析成 GalleryLayer[]。
 *
 * 防御:
 *  - undefined / 空串 → 空数组(条目数据缺失,不抛错让 UI 友好降级)
 *  - 非 JSON / 非数组 → 空数组,不抛错(老数据/手工编辑容错)
 *  - 数组里 assetPath 缺失/非字符串的项 → 丢弃(防止运行时 resolve undefined 黑屏)
 */
export function parseLayersJson(
  raw: string | undefined | null,
): GalleryLayer[] {
  if (typeof raw !== "string" || !raw.trim()) return [];
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return [];
  }
  if (!Array.isArray(parsed)) return [];
  const out: GalleryLayer[] = [];
  for (const item of parsed) {
    if (!item || typeof item !== "object") continue;
    const layer = item as Record<string, unknown>;
    if (typeof layer.assetPath !== "string" || !layer.assetPath.trim()) {
      continue;
    }
    out.push({
      assetPath: layer.assetPath,
      distance:
        typeof layer.distance === "number" ? layer.distance : undefined,
      offset: typeof layer.offset === "string" ? layer.offset : undefined,
      name: typeof layer.name === "string" ? layer.name : undefined,
    });
  }
  return out;
}

/**
 * 合法鉴赏条目:entryId / sceneId 都是非空字符串,layers 非空且每层 assetPath OK。
 * 用于过滤存档里历史脏数据,避免渲染时炸。
 */
export function isValidEntry(e: GalleryEntry): boolean {
  if (!e) return false;
  if (typeof e.entryId !== "string" || !e.entryId) return false;
  if (typeof e.sceneId !== "string" || !e.sceneId) return false;
  if (!Array.isArray(e.layers) || e.layers.length === 0) return false;
  for (const l of e.layers) {
    if (!l || typeof l.assetPath !== "string" || !l.assetPath) return false;
  }
  return true;
}

/** 过滤音乐鉴赏的历史脏数据，避免把空资源交给播放器。 */
export function isValidMusicEntry(e: MusicGalleryEntry): boolean {
  if (!e) return false;
  if (typeof e.entryId !== "string" || !e.entryId.trim()) return false;
  if (typeof e.title !== "string" || !e.title.trim()) return false;
  return typeof e.audioUri === "string" && e.audioUri.trim().length > 0;
}

/** 过滤剧情片段鉴赏的历史脏数据，片段 id 是唯一必需的回放定位信息。 */
export function isValidFragmentEntry(e: FragmentGalleryEntry): boolean {
  if (!e) return false;
  if (typeof e.entryId !== "string" || !e.entryId.trim()) return false;
  if (typeof e.title !== "string" || !e.title.trim()) return false;
  return typeof e.fragmentId === "string" && e.fragmentId.trim().length > 0;
}

/** 从任意入参中取经过 trim 的非空字符串。 */
export function optionalText(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const text = value.trim();
  return text || undefined;
}

/**
 * 鉴赏条目标题的三级回退:
 *   创作者填的 title → Inspector 写入的场景名(_sceneName)→ sceneId 兜底。
 * 前两级都 trim 后取首个非空,绝不让 uuid 露脸(除非真的什么名都没有)。
 */
export function resolveGalleryTitle(input: {
  customTitle?: unknown;
  sceneName?: unknown;
  sceneId: string;
}): string {
  const custom =
    typeof input.customTitle === "string" ? input.customTitle.trim() : "";
  const name =
    typeof input.sceneName === "string" ? input.sceneName.trim() : "";
  return custom || name || input.sceneId;
}

/**
 * 从 layers 拍平一张封面 assetPath —— 取首个有 assetPath 的层;都没有则空串。
 * 供 data-list 的 imageField 绑定(它只能取顶层字符串,取不到嵌套 layers)。
 */
export function deriveCoverImage(layers: GalleryLayer[]): string {
  for (const l of layers) {
    if (l && typeof l.assetPath === "string" && l.assetPath.trim()) {
      return l.assetPath;
    }
  }
  return "";
}
