/** 设置菜单与持久化共用 0-100；50 是作者基础速度的 1x。 */
export const NEUTRAL_TEXT_SPEED_SETTING = 50;
export const MAX_TEXT_SPEED_SETTING = 100;
export const MAX_FINITE_TEXT_SPEED_SETTING = 99;
export const CURRENT_TEXT_SPEED_SETTING_VERSION = 2;

/** 旧存档以 70ms 作为默认间隔；迁移时把它解释为新模型的 1x。 */
export const LEGACY_NEUTRAL_TEXT_INTERVAL = 70;

export const MIN_TEXT_SPEED_MULTIPLIER = 0.5;
export const MAX_FINITE_TEXT_SPEED_MULTIPLIER =
  2 ** ((MAX_FINITE_TEXT_SPEED_SETTING - NEUTRAL_TEXT_SPEED_SETTING) / 25);

function finiteNumericValue(value: unknown): number | null {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value !== "string" || value.trim() === "") return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

export function normalizeTextSpeedSetting(value: unknown): number {
  const numeric = finiteNumericValue(value);
  if (numeric === null) return NEUTRAL_TEXT_SPEED_SETTING;
  return Math.round(Math.max(0, Math.min(MAX_TEXT_SPEED_SETTING, numeric)));
}

/**
 * 菜单值转阅读速度倍率。
 *
 * 0→0.5x、50→1x、75→2x、99→约 4x；100 是独立的瞬显端点。
 * 两段指数曲线让滑块每一段的体感变化均匀，同时保留清晰锚点。
 */
export function textSpeedSettingToSpeedMultiplier(setting: unknown): number {
  const normalized = normalizeTextSpeedSetting(setting);
  if (normalized === MAX_TEXT_SPEED_SETTING) {
    return Number.POSITIVE_INFINITY;
  }
  if (normalized <= NEUTRAL_TEXT_SPEED_SETTING) {
    return 2 ** ((normalized - NEUTRAL_TEXT_SPEED_SETTING) / 50);
  }
  return 2 ** ((normalized - NEUTRAL_TEXT_SPEED_SETTING) / 25);
}

/** 把旧间隔模型的相对快慢迁移到新菜单值。 */
export function legacyTextIntervalToPlayerSetting(intervalMs: unknown): number {
  const interval = finiteNumericValue(intervalMs);
  if (interval === null || interval < 0) {
    return NEUTRAL_TEXT_SPEED_SETTING;
  }
  if (interval === 0) return MAX_TEXT_SPEED_SETTING;

  const multiplier = LEGACY_NEUTRAL_TEXT_INTERVAL / interval;
  if (multiplier <= MIN_TEXT_SPEED_MULTIPLIER) return 0;
  if (multiplier <= 1) {
    return normalizeTextSpeedSetting(
      NEUTRAL_TEXT_SPEED_SETTING + 50 * Math.log2(multiplier),
    );
  }
  if (multiplier >= MAX_FINITE_TEXT_SPEED_MULTIPLIER) {
    return MAX_FINITE_TEXT_SPEED_SETTING;
  }
  return Math.min(
    MAX_FINITE_TEXT_SPEED_SETTING,
    normalizeTextSpeedSetting(
      NEUTRAL_TEXT_SPEED_SETTING + 25 * Math.log2(multiplier),
    ),
  );
}

/**
 * 把玩家设置叠加到作者当前给出的基础每字间隔上。
 *
 * `baseIntervalMs` 可以来自对话框样式、剧本中的动态文字参数、逐句覆盖或
 * 扩展 style hook；玩家滑块只决定倍率，不反向修改这些作者运行时状态。
 * 设置值越大，最终间隔越短；100 直接返回 0ms。
 */
export function scaleTextIntervalByPlayerSetting(
  baseIntervalMs: number,
  playerSetting: number,
): number {
  const base = Number.isFinite(baseIntervalMs)
    ? Math.max(0, baseIntervalMs)
    : 0;
  const multiplier = textSpeedSettingToSpeedMultiplier(playerSetting);
  return Number.isFinite(multiplier) ? base / multiplier : 0;
}
